from dataclasses import dataclass, field
import copy

@dataclass
class Parameter:
    name: str
    value: float
    units: str
    options: str
    desc: str
    group: str = ""
    type: str = "FLOAT"
    min_val: str = ""
    max_val: str = ""
    modified: bool = False
    favourite: bool = False

