def get_default_params():
    """Always return a fresh deep copy so resets work cleanly."""
    return copy.deepcopy(DEFAULT_PARAMS)

def get_groups():
    """Return sorted list of unique group names."""
    return sorted(set(p.group for p in DEFAULT_PARAMS))